/**
 * The 24 solar terms — English edition of the term details.
 *
 * Translated from src/data/termDetails.ts (Chinese source).
 * The three pentads (三候) follow the received text of Wu Cheng's
 * "Seventy-two Phenological Notes of the Monthly Ordinances" (Yuan dynasty).
 * Solar longitude, season and order correspond strictly to index 0..23.
 * Temperature, phenology and farming notes preserve the source's regional
 * contrasts, so that no local phenomenon is presented as nationwide.
 */

export interface PentadEn {
  zh: string   // 中文原文，如 '东风解冻'
  en: string   // 英文释义，如 'The east wind thaws the ice'
}

export interface PoemEn {
  zh: string       // 中文原句（保留汉字，不要改成拼音）
  en: string       // 英文译文
  author: string   // 如 'Zhang Shi（张栻）' —— 英文名 + 括号内汉字
  source: string   // 如 'On the Arrival of Spring（《立春偶成》）'
}

export interface ProverbEn {
  zh: string   // 中文农谚原文
  en: string   // 英文译文
}

export interface TermDetailEn {
  index: number
  name: string      // 英文节气名，必须严格用下表给出的写法
  nameZh: string    // 中文节气名，如 '立春'
  pinyin: string    // 带声调拼音，与中文源文件一致
  longitude: number
  season: 'Spring' | 'Summer' | 'Autumn' | 'Winter'
  meaning: string      // 名称含义
  climate: string      // 典型气候
  phenology: string    // 物候现象
  pentads: [PentadEn, PentadEn, PentadEn]
  farming: string      // 农事活动
  custom: string       // 传统习俗
  food: string         // 代表性饮食
  poem?: PoemEn
  proverb?: ProverbEn
}

